import { ResponseError } from "../../errors.js";
import { Writer } from "../../protocol/writer.js";
import { createAPI } from "../definitions.js";
/* AlterReplicaLogDirs Request (Version: 0) => [dirs]; dirs => path [topics]; topics => name [partitions] */
export function createRequest(dirs) {
    return Writer.create().appendArray(dirs, (w, d) => w
        .appendString(d.path, false)
        .appendArray(d.topics, (w, t) => w.appendString(t.name, false).appendArray(t.partitions, (w, p) => w.appendInt32(p), false, false), false, false), false, false);
}
/* AlterReplicaLogDirs Response (Version: 0) => throttle_time_ms [results]; results => topic_name [partitions]; partitions => partition_index error_code */
export function parseResponse(_, apiKey, apiVersion, reader) {
    const errors = [];
    const response = {
        throttleTimeMs: reader.readInt32(),
        results: reader.readArray((r, i) => ({
            topicName: r.readString(false),
            partitions: r.readArray((r, j) => {
                const partition = { partitionIndex: r.readInt32(), errorCode: r.readInt16() };
                if (partition.errorCode)
                    errors.push([`/results/${i}/partitions/${j}`, [partition.errorCode, null]]);
                return partition;
            }, false, false)
        }), false, false)
    };
    if (errors.length)
        throw new ResponseError(apiKey, apiVersion, Object.fromEntries(errors), response);
    return response;
}
export const api = createAPI(34, 0, createRequest, parseResponse, false, false);
